17: enum ArchiveReader {
18:     static let maxExtracted = 80 * 1024 * 1024
19:     static func candidates(fileName: String, data: Data) throws -> [EmbeddedBinary] {
20:         let name = fileName.lowercased()
21:         if name.hasSuffix(".ipa") || data.starts(with: [0x50,0x4b,0x03,0x04]) { return try zip(data) }
22:         if name.hasSuffix(".deb") || data.starts(with: Array("!<arch>\n".utf8)) { return try deb(data) }
23:         return [EmbeddedBinary(path: fileName, data: data)]
24:     }
25:     private static func inflate(_ bytes: Data, expected: Int, bits: Int) -> Data? {
26:         guard expected > 0, expected <= maxExtracted else { return nil }
27:         var output = Data(count: expected)
28:         let result = bytes.withUnsafeBytes { src in
29:             output.withUnsafeMutableBytes { dst in
30:                 rl_inflate(src.bindMemory(to: UInt8.self).baseAddress, bytes.count,
31:                            dst.bindMemory(to: UInt8.self).baseAddress, expected, Int32(bits))
32:             }
33:         }
34:         return result == 0 ? output : nil
35:     }
36:     private static func zip(_ data: Data) throws -> [EmbeddedBinary] {
37:         let r = BinaryReader(data: data)
38:         guard data.count >= 22 else { throw ArchiveFailure.unsupported("ZIP 文件不完整") }
39:         let lower = max(0, data.count - 65557)
40:         guard let eocd = stride(from: data.count - 22, through: lower, by: -1).first(where: { r.u32($0) == 0x06054b50 }),
41:               let count = r.u16(eocd + 10), let central = r.u32(eocd + 16) else {
42:             throw ArchiveFailure.unsupported("找不到 ZIP 中央目录；暂不支持 ZIP64")
43:         }
44:         var cursor = Int(central)
45:         var found: [EmbeddedBinary] = []
46:         for _ in 0..<min(Int(count), 10000) {
47:             guard r.u32(cursor) == 0x02014b50, let method = r.u16(cursor+10),
48:                   let compressed = r.u32(cursor+20), let original = r.u32(cursor+24),
49:                   let nameLen = r.u16(cursor+28), let extra = r.u16(cursor+30),
50:                   let comment = r.u16(cursor+32), let local = r.u32(cursor+42) else { break }
51:             let path = r.text(cursor+46, Int(nameLen))
52:             let step = 46 + Int(nameLen) + Int(extra) + Int(comment)
53:             guard step > 0, cursor + step <= data.count else { break }
54:             cursor += step
55:             guard path.lowercased().hasSuffix(".dylib") || (path.hasPrefix("Payload/") && path.contains(".app/") && !path.hasSuffix("/")) else { continue }
56:             let start = Int(local)
57:             guard r.u32(start) == 0x04034b50, let localName = r.u16(start+26), let localExtra = r.u16(start+28) else { continue }
58:             let offset = start + 30 + Int(localName) + Int(localExtra)
59:             guard Int(compressed) <= maxExtracted, Int(original) <= maxExtracted,
60:                   offset >= 0, offset <= data.count, Int(compressed) <= data.count - offset else { continue }
61:             let bytes = data.subdata(in: offset..<offset+Int(compressed))
62:             let unpacked: Data?
63:             if method == 0 { unpacked = bytes }
64:             else if method == 8 { unpacked = inflate(bytes, expected: Int(original), bits: -15) }
65:             else { unpacked = nil }
66:             if let unpacked = unpacked, MachOAnalyzer.isMachO(unpacked) {
67:                 found.append(EmbeddedBinary(path: path, data: unpacked))
68:             }
69:         }
70:         return found
71:     }
72:     private static func deb(_ data: Data) throws -> [EmbeddedBinary] {
73:         let r = BinaryReader(data: data)
74:         guard data.starts(with: Array("!<arch>\n".utf8)) else { throw ArchiveFailure.unsupported("DEB 的 ar 文件头无效") }
75:         var cursor = 8
76:         while cursor + 60 <= data.count {
77:             let name = r.text(cursor, 16).trimmingCharacters(in: CharacterSet(charactersIn: "/ "))
78:             guard let size = Int(r.text(cursor+48, 10)), size >= 0 else { break }
79:             let start = cursor + 60
80:             guard start <= data.count, size <= data.count - start else { break }
81:             if name.hasPrefix("data.tar") {
82:                 let payload = data.subdata(in: start..<start+size)
83:                 if name.hasSuffix(".gz") {
84:                     guard let tar = gzip(payload) else { throw ArchiveFailure.unsupported("DEB gzip 数据解压失败或文件过大") }
85:                     return tarCandidates(tar)
86:                 }
87:                 if name == "data.tar" { return tarCandidates(payload) }
88:                 throw ArchiveFailure.unsupported("此 DEB 使用 \(name)。V1 暂不支持 xz/zstd，请先提取 dylib 再导入")
89:             }
90:             cursor = start + size + (size % 2)
91:         }
92:         throw ArchiveFailure.unsupported("DEB 中未找到 data.tar")
93:     }
94:     private static func gzip(_ data: Data) -> Data? {
95:         // Gzip uncompressed size is stored modulo 2^32 in the last 4 bytes.
96:         guard data.count >= 18 else { return nil }
97:         let r = BinaryReader(data: data)
98:         guard let size = r.u32(data.count-4), size > 0 else { return nil }
99:         return inflate(data, expected: Int(size), bits: 31)
100:     }
101:     private static func tarCandidates(_ data: Data) -> [EmbeddedBinary] {
102:         let r = BinaryReader(data: data)
103:         var offset = 0
104:         var result: [EmbeddedBinary] = []
105:         while offset + 512 <= data.count {
106:             let name = r.text(offset, 100)
107:             if name.isEmpty { break }
108:             let sizeString = r.text(offset+124, 12).trimmingCharacters(in: .whitespacesAndNewlines)
109:             let size = Int(sizeString, radix: 8) ?? 0
110:             let body = offset + 512
111:             guard size >= 0, body <= data.count, size <= data.count-body else { break }
112:             if name.lowercased().hasSuffix(".dylib"), size <= maxExtracted {
113:                 let bytes = data.subdata(in: body..<body+size)
114:                 if MachOAnalyzer.isMachO(bytes) { result.append(EmbeddedBinary(path: name, data: bytes)) }
115:             }
116:             offset = body + ((size + 511) / 512) * 512
117:         }
118:         return result
119:     }
120: }

